            BigDecimal claimed = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.countsClaimed(c, today)
                            && !c.isDeferredOn(today) && c.getCorrects() == null)
                    .map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
