1044	    return GRADES.map((grade) => {
1045	      const onGrade = current.filter((p) => this.gradeToday(p) === grade);
1046	      return {
1047	        grade,
1048	        count: onGrade.length,
1049	        dueTotal: money(onGrade.reduce((sum, p) => sum + (due.get(p.id) ?? 0), 0)),
1050	        active: onGrade.filter((p) => active.get(p.id)).length,
1051	      };
1052	    });
1053	  });
1054	  /** Per period: its due-total, as its row shows it, and its change from the period before it by start date (none
1055	   *  for the earliest). */
1056	  protected readonly summaryByPeriod = computed<PeriodSummary[]>(() => {
1057	    const due = this.dueByPeriod();
1058	    const list = this.periods.list();
1059	    const byStart = [...list].sort((a, b) => a.from.localeCompare(b.from) || a.id - b.id);
1060	    const change = new Map(byStart.map((p, i) => [p.id, i === 0 ? ''
1061	      : money(cents(due.get(p.id) ?? '0.00') - cents(due.get(byStart[i - 1].id) ?? '0.00'))]));
1062	    return list.map((p) => ({ name: p.name, dueTotal: due.get(p.id) ?? '0.00', change: change.get(p.id) ?? '' }));
1063	  });
1064	  /** Per status: how many of the sheet's claims are in it. */
1065	  protected readonly summaryByStatus = computed<StatusSummary[]>(() => {
1066	    const claims = this.claims();
1067	    return SUMMARY_STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
1068	  });
1069	  /** How many of the sheet's claims are in a status. */
1070	  protected statusCount(status: string): number {
1071	    return this.summaryByStatus().find((s) => s.status === status)?.count ?? 0;
1072	  }
1073	  /** How many of the sheet's claims are late for review on its today. */
1074	  protected readonly reviewLateCount = computed(() => {
1075	    const sheet = this.sheets.current();
1076	    if (sheet === null) return 0;
1077	    return this.claims().filter((c) => isReviewLate(c, sheet.today, sheet.reviewSla)).length;
1078	  });
1079	  protected readonly voidReasons = inject(VoidReasons);
1080	  /** Per reason on the sheet's list, how many VOID claims were voided with it. */

