-- A claim's lines, in the order added (by seq): each with a label, a quantity and a unit amount; a claim with
-- lines has as its amount the quantities times the unit amounts added up.
CREATE TABLE claim_line (
    claim_id   BIGINT         NOT NULL REFERENCES claim (id),
    seq        INT            NOT NULL,
    line_label VARCHAR(200)   NOT NULL,
    qty        INT            NOT NULL,
    unit       DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;

/** A line of a claim: a label, a quantity (a whole number, at least 1) and a unit amount (two decimals). */
@Embeddable
public class ClaimLine {

    @Column(name = "line_label", nullable = false, length = 200)
    private String label;

    @Column(name = "qty", nullable = false)
    private int qty;

    @Column(name = "unit", nullable = false, precision = 14, scale = 2)
    private BigDecimal unit;

    protected ClaimLine() {
    }

    public ClaimLine(String label, int qty, BigDecimal unit) {
        this.label = label;
        this.qty = qty;
