content.content:
  /** The reason from the sheet's list the claim was voided with; null when not void or voided without one. */
  voidReason: string | null;
  /** The claim's comments, oldest first. */
  comments: ClaimComment[];
  /** The signed-in name of the user who last edited the claim; null if no one has. Like its opener, they
   *  cannot settle or approve it. */
  editedBy: string | null;
  /** The number of the settle batch that settled the claim; null when it was not settled by one. */
  batch: number | null;
  /** The claim's lines, in the order added; while it has any, its amount is their totals added up. */
  lines: ClaimLine[];
}

/** A line of a claim: its label, its quantity (a whole number, at least 1) and its unit amount with exactly two
 *  decimals. */
export interface ClaimLine {
  label: string;
  qty: number;
  unit: string;
}

/** A comment on a claim: the signed-in name of who wrote it, the sheet's today (yyyy-mm-dd) then, and its text. */
export interface ClaimComment {
  by: string;
  on: string;
  text: string;
          @if (voidReasons.all().length > 0) {
            <label [for]="'claim-void-reason-' + c.id">Reason to void</label>
            <select [id]="'claim-void-reason-' + c.id" data-testid="claim-void-reason"
                    [value]="chosenVoidReasons()[c.id] ?? ''" (change)="voidReasonChanged(c, $any($event.target).value)">
              <option value="">Choose a reason</option>
              @for (r of voidReasons.all(); track r.id) {
                <option [value]="r.reason">{{ r.reason }}</option>
              }
            </select>
          }
          <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'VOID')"
                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
          <button type="button" data-testid="claim-delete" (click)="changeStatus(c, 'DELETED')"
                  [attr.aria-label]="'Delete claim of ' + c.amount + ' on ' + c.date">Delete</button>
          <button type="button" data-testid="claim-restore" (click)="changeStatus(c, 'DRAFT')"
                  [attr.aria-label]="'Restore claim of ' + c.amount + ' on ' + c.date">Restore</button>
          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
          <select [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to"
                  [value]="reassignTo()[c.id] ?? ''" (change)="reassignToChanged(c, $any($event.target).value)">
            <option value="">Choose a person</option>
            @for (o of others(); track o.id) {
              <option [value]="o.id">{{ o.name }}</option>
            }
          </select>
          <button type="button" data-testid="claim-reassign" (click)="reassign(c)"
                  [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
          <label [for]="'claim-inline-amount-' + c.id">New amount</label>
          <input [id]="'claim-inline-amount-' + c.id" data-testid="claim-inline-amount" inputmode="decimal"
                 autocomplete="off" [value]="inlineAmounts()[c.id] ?? ''"
                 (input)="inlineAmountChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-inline-save" (click)="saveInline(c)"
                  [attr.aria-label]="'Save the amount of claim of ' + c.amount + ' on ' + c.date">Save amount</button>
          @if (editingId() === c.id) {
            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
          } @else {
            <button type="button" data-testid="claim-edit" (click)="edit(c)"
                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          }
          <button type="button" data-testid="claim-timeline" (click)="showTimeline(c)"
                  [attr.aria-label]="'Show the timeline of claim of ' + c.amount + ' on ' + c.date">Timeline</button>
          <ol [attr.aria-label]="'Timeline of claim of ' + c.amount + ' on ' + c.date">
            @for (line of timelines()[c.id] ?? []; track $index) {
              <li data-testid="claim-timeline-line">{{ line }}</li>
            }
          </ol>
          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
            @for (l of c.log; track $index) {
              <li data-testid="claim-log-line">{{ l.status }} by {{ l.by }} on {{ l.on }} due={{ l.due ?? notAvailable }}</li>
            }
          </ol>
          <ol [attr.aria-label]="'Lines of claim of ' + c.amount + ' on ' + c.date">
            @for (l of c.lines ?? []; track $index) {
              <li data-testid="claim-lines-line">{{ l.label }} {{ l.qty }} x {{ l.unit }}</li>
            }
          </ol>
          <label [for]="'claim-line-label-' + c.id">Line label</label>
          <input [id]="'claim-line-label-' + c.id" data-testid="claim-line-label" autocomplete="off"
                 [value]="lineDrafts()[c.id]?.label ?? ''" (input)="lineChanged(c, 'label', $any($event.target).value)" />
          <label [for]="'claim-line-qty-' + c.id">Quantity</label>
          <input [id]="'claim-line-qty-' + c.id" data-testid="claim-line-qty" inputmode="numeric" autocomplete="off"
                 [value]="lineDrafts()[c.id]?.qty ?? ''" (input)="lineChanged(c, 'qty', $any($event.target).value)" />
          <label [for]="'claim-line-unit-' + c.id">Unit amount</label>
          <input [id]="'claim-line-unit-' + c.id" data-testid="claim-line-unit" inputmode="decimal" autocomplete="off"
                 [value]="lineDrafts()[c.id]?.unit ?? ''" (input)="lineChanged(c, 'unit', $any($event.target).value)" />
          <button type="button" data-testid="claim-line-add" (click)="addLine(c)"
                  [attr.aria-label]="'Add a line to claim of ' + c.amount + ' on ' + c.date">Add line</button>
          <ol [attr.aria-label]="'Comments on claim of ' + c.amount + ' on ' + c.date">
            @for (m of c.comments ?? []; track $index) {
              <li data-testid="claim-comments-line">{{ m.by }} on {{ m.on }}: {{ m.text }}</li>
            }
          </ol>
          <label [for]="'claim-comment-text-' + c.id">Comment</label>
          <input [id]="'claim-comment-text-' + c.id" data-testid="claim-comment-text" autocomplete="off"
                 [value]="commentTexts()[c.id] ?? ''" (input)="commentTextChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-comment-add" (click)="addComment(c)"
                  [attr.aria-label]="'Comment on claim of ' + c.amount + ' on ' + c.date">Add comment</button>
          @if (claimError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly sheets = inject(Sheets);
  protected readonly session = inject(Session);
  private readonly api = inject(Claims);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<ClaimView[]>();
  /** The rates of each grade, in the order they take effect. */
  readonly ratesByGrade = input.required<ReadonlyMap<Grade, RateLine>>();
  /** This person's grades: a claim is at the one in force on its date. */
  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
  /** The sheet's periods, by from-date. */
  readonly periods = input.required<readonly PeriodView[]>();
  /** The other people on the sheet a claim can be moved to. */
  readonly others = input<readonly Pick<PersonView, 'id' | 'name'>[]>([]);
  /** The person's holds: they no longer take any claim out of a total; only the pools' cuts heed them. */
  readonly holds = input<readonly HoldView[]>([]);
